'use server'

import { updateTag } from 'next/cache'

export async function createPost(formData: FormData) {
  const title = formData.get('title')
  const content = formData.get('content')

  // Validate input
  if (!title || typeof title !== 'string') {
    throw new Error('Title is required')
  }

  if (!content || typeof content !== 'string') {
    throw new Error('Content is required')
  }

  // Create the post (replace with your actual database logic)
  // Example: await db.post.create({ data: { title, content } })
  console.log('Creating post:', { title, content })

  // Simulate async database operation
  await new Promise(resolve => setTimeout(resolve, 100))

  // Invalidate the "posts" cache tag
  // This ensures the next request will wait for fresh data
  // rather than serving stale cached content
  updateTag('posts')

  return { success: true }
}

